import{_ as t,o as r,c as i,a3 as o}from"./chunks/framework.BHpftTUY.js";const h=JSON.parse('{"title":"Security policy","description":"How to report a security vulnerability in yarilo privately: supported versions, the GitHub reporting form or email, what to include, when you hear back, and no bounty program.","frontmatter":{"description":"How to report a security vulnerability in yarilo privately: supported versions, the GitHub reporting form or email, what to include, when you hear back, and no bounty program.","head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/operations/security.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/2.4.5/operations/security.html"}],["meta",{"property":"og:title","content":"Security policy"}],["meta",{"name":"twitter:title","content":"Security policy"}],["meta",{"property":"og:description","content":"How to report a security vulnerability in yarilo privately: supported versions, the GitHub reporting form or email, what to include, when you hear back, and no bounty program."}],["meta",{"name":"twitter:description","content":"How to report a security vulnerability in yarilo privately: supported versions, the GitHub reporting form or email, what to include, when you hear back, and no bounty program."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/2.4.5/operations/security.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/2.4.5/operations/security.html\\",\\"headline\\":\\"Security policy\\",\\"description\\":\\"How to report a security vulnerability in yarilo privately: supported versions, the GitHub reporting form or email, what to include, when you hear back, and no bounty program.\\",\\"dateModified\\":\\"2026-10-24T16:57:35.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Security policy\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/operations/security.html\\"}]}]}"]]},"headers":[],"relativePath":"operations/security.md","filePath":"operations/security.md","lastUpdated":1792861055000}'),a={name:"operations/security.md"};function n(s,e,l,p,c,u){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="security-policy" tabindex="-1">Security policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to &quot;Security policy&quot;">​</a></h1><p>Do not report security issues in public issues, pull requests or discussions. Report them privately, so the issue can be fixed before it is disclosed.</p><h2 id="supported-versions" tabindex="-1">Supported versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported versions&quot;">​</a></h2><p>Security fixes go into the latest release of the current stable line (2.4.x). Upgrade to it before reporting.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h2><p>Use one of these channels:</p><ul><li>the <strong>Report a vulnerability</strong> button on the <a href="https://github.com/yarilomail/yarilo/security" target="_blank" rel="noreferrer">repository&#39;s Security tab</a> (preferred)</li><li>email to <a href="mailto:security@yarilomail.org" target="_blank" rel="noreferrer">security@yarilomail.org</a></li></ul><p>Include the affected version, the relevant part of the configuration, steps to reproduce, and the impact you observed.</p><p>We acknowledge a report within 7 days.</p><h2 id="bounties" tabindex="-1">Bounties <a class="header-anchor" href="#bounties" aria-label="Permalink to &quot;Bounties&quot;">​</a></h2><p>There is no bounty program.</p><h2 id="advisories" tabindex="-1">Advisories <a class="header-anchor" href="#advisories" aria-label="Permalink to &quot;Advisories&quot;">​</a></h2><p>Published advisories and the full policy are at <a href="https://yarilomail.org/security.html" target="_blank" rel="noreferrer">yarilomail.org/security.html</a>.</p><p>Fixes with no advisory of their own are listed under Security in the release notes. In 2.4.4 that is <a href="https://github.com/yarilomail/yarilo/issues/2297" target="_blank" rel="noreferrer">#2297</a>: <code>require &quot;ihave&quot;</code> bypassed the <code>sieve_<wbr>extensions</code> whitelist, but only on installations that had added <code>ihave</code> to <code>sieve_<wbr>extensions</code>; the default list does not include it.</p>',14)])])}const y=t(a,[["render",n]]);export{h as __pageData,y as default};
